                if grid[i][j] == ".":
                    count += 1
                else:
                    count = 0
                    total += 1 if i == h-1 else 0

            total += count
            count = 0

        return total

    return min(grid2hor_index(h, w, n, grid), grid2vert_index(h, w, n, grid))
